"""GENERATED by scripts/place_hinge_hardware_fusion.py -- do not edit this file.

Every number below comes from design/hinge.py. Regenerate rather than patch.

Servo origin radius   33.1850 mm (servo_output_face)
Bearing origin radius 39.7000 mm (bearing_outboard = tube_outer_radius)
Hinge Z               68.2690 mm (module frame)
"""


import math

import adsk.core
import adsk.fusion


def _box(tbm, cx, cy, cz, lx, ly, lz):
    """An axis-aligned box in the GLOBAL X/Y/Z frame. mm in, cm internally."""
    obb = adsk.core.OrientedBoundingBox3D.create(
        adsk.core.Point3D.create(cx / 10.0, cy / 10.0, cz / 10.0),
        adsk.core.Vector3D.create(1.0, 0.0, 0.0),
        adsk.core.Vector3D.create(0.0, 1.0, 0.0),
        lx / 10.0, ly / 10.0, lz / 10.0)
    return tbm.createBox(obb)


def _cyl(tbm, x, y, z0, z1, r):
    """A cylinder on an axis PARALLEL TO Z, from z0 to z1. mm in, cm internally."""
    return tbm.createCylinderOrCone(
        adsk.core.Point3D.create(x / 10.0, y / 10.0, z0 / 10.0), r / 10.0,
        adsk.core.Point3D.create(x / 10.0, y / 10.0, z1 / 10.0), r / 10.0)


def _quadrant_axes(quadrant):
    """u = radial direction, v = tangential direction, at 90 deg * quadrant about Z."""
    a = math.radians(quadrant * 90.0)
    u = adsk.core.Vector3D.create(math.cos(a), math.sin(a), 0.0)
    v = adsk.core.Vector3D.create(-math.sin(a), math.cos(a), 0.0)
    return u, v


def _quadrant_box(tbm, quadrant, r_lo, r_hi, y_lo, y_hi, z_lo, z_hi):
    """A box whose length runs radially and width tangentially, at a given quadrant
    (0/1/2/3 = 0/90/180/270 deg about the rocket Z axis) -- ports
    `cad/canard_bay.fs`'s `quadrantCuboid`. mm in, cm internally.
    """
    u, v = _quadrant_axes(quadrant)
    r_lo, r_hi = min(r_lo, r_hi), max(r_lo, r_hi)
    y_lo, y_hi = min(y_lo, y_hi), max(y_lo, y_hi)
    z_lo, z_hi = min(z_lo, z_hi), max(z_lo, z_hi)
    rc, yc, zc = (r_lo + r_hi) / 2.0, (y_lo + y_hi) / 2.0, (z_lo + z_hi) / 2.0
    center = adsk.core.Point3D.create(
        (u.x * rc + v.x * yc) / 10.0, (u.y * rc + v.y * yc) / 10.0, zc / 10.0)
    obb = adsk.core.OrientedBoundingBox3D.create(
        center, u, v, (r_hi - r_lo) / 10.0, (y_hi - y_lo) / 10.0, (z_hi - z_lo) / 10.0)
    return tbm.createBox(obb)


def _radial_cyl(tbm, quadrant, across, z, r0, r1, r):
    """A cylinder on a RADIAL axis at the given quadrant, spanning radius r0 -> r1, offset
    `across` tangentially -- ports `cad/canard_bay.fs`'s `radialCylinder`. mm in, cm
    internally.
    """
    u, v = _quadrant_axes(quadrant)
    bx, by = v.x * across, v.y * across
    p0 = adsk.core.Point3D.create((bx + u.x * r0) / 10.0, (by + u.y * r0) / 10.0, z / 10.0)
    p1 = adsk.core.Point3D.create((bx + u.x * r1) / 10.0, (by + u.y * r1) / 10.0, z / 10.0)
    return tbm.createCylinderOrCone(p0, r / 10.0, p1, r / 10.0)


def _cut(tbm, target, tool, what):
    """Boolean subtract. NOTE: booleanOperation returns a BOOL and mutates `target` in
    place -- never assign its result back, per make_sled_fusion.py's own warning.
    """
    if not tbm.booleanOperation(target, tool, adsk.fusion.BooleanTypes.DifferenceBooleanType):
        raise ValueError("cut %s did not take" % what)


def _union(tbm, target, tool, what):
    if not tbm.booleanOperation(target, tool, adsk.fusion.BooleanTypes.UnionBooleanType):
        raise ValueError("union %s did not take" % what)


def _get_or_create_component(root, name):
    """Find an existing occurrence by component name, else create a new empty one.

    Returns (occurrence, already_has_bodies). A caller that finds `already_has_bodies`
    True should verify rather than rebuild -- the same idempotency rule
    `make_sled_fusion.py` uses.
    """
    for o in root.occurrences:
        if o.component.name == name:
            return o, o.component.bRepBodies.count > 0
    occ = root.occurrences.addNewComponent(adsk.core.Matrix3D.create())
    occ.component.name = name
    return occ, False


def _inject(comp, made):
    """Inject a list of (name, body) temporary BRep bodies through one BaseFeature.

    Mandatory for a parametric document: a temp body only "takes" via
    `BRepBodies.add(body, baseFeature)`, per make_sled_fusion.py's own header.
    """
    bf = comp.features.baseFeatures.add()
    bf.startEdit()
    for (name, body) in made:
        b = comp.bRepBodies.add(body, bf)
        b.name = name
    bf.finishEdit()


def _verify_volume(comp, want, tol, loose=(), loose_tol=None):
    """Compare each named body's volume (mm3) against an analytic expectation.

    `loose` names bodies (radial holes through curved walls, or a part whose analytic
    figure is itself an estimate) that get `loose_tol` instead of `tol` -- measured, not
    guessed, the same discipline make_sled_fusion.py's PORT_VOLUME_TOLERANCE_PER_PORT uses.
    Returns a list of violation strings (empty if everything is within tolerance).
    """
    acc = adsk.fusion.CalculationAccuracy.VeryHighCalculationAccuracy
    got = {}
    for b in comp.bRepBodies:
        got[b.name] = b.getPhysicalProperties(acc).volume * 1e3
    bad = []
    for name, wv in want.items():
        if name not in got:
            bad.append("%s is missing" % name)
            continue
        t = loose_tol if (name in loose and loose_tol is not None) else tol
        d = got[name] - wv
        print("  %-28s %14.4f mm3  want %14.4f  delta %+9.4f  (tol %.3f)"
              % (name, got[name], wv, d, t))
        if abs(d) > t:
            bad.append("%s is %+.4f mm3 out" % (name, d))
    return bad


def _verify_cyl_faces(body, radius, axis_is_radial):
    """Count cylindrical faces at `radius` (mm) and read back their clocking, in degrees
    mod 180. `axis_is_radial` True keeps only faces whose axis has no Z component (a
    radial hole); False keeps only faces whose axis IS parallel to Z (an axial hole).
    Exact where a volume check on a radial hole through a curved wall is not -- see
    make_sled_fusion.py's header for why that matters.
    """
    found = []
    for f in body.faces:
        g = f.geometry
        if not g.objectType.endswith("Cylinder"):
            continue
        if abs(g.radius * 10.0 - radius) > 1e-6:
            continue
        ax = g.axis
        is_radial = abs(ax.z) < 1e-9
        if is_radial != axis_is_radial:
            continue
        found.append(math.degrees(math.atan2(ax.y, ax.x)) % 180.0)
    return sorted(found)


HINGE_Z = 68.2690
SERVO_ORIGIN_R = 33.1850
BEARING_ORIGIN_R = 39.7000
ANGLE_TOLERANCE_DEG = 1e-06


def _find(root, name):
    for o in root.occurrences:
        if o.component.name == name:
            return o
    raise ValueError("no occurrence named %r -- run the M2 generators first" % name)


def _place_hinge_frame(tbm, body, quadrant, origin_r):
    """Copy `body` out of its local hinge-axis frame and place it on hinge axis
    `quadrant` (0/1/2/3 = 0/90/180/270 deg) at radius `origin_r`, HINGE_Z axially.
    Local +X (along) -> global +Z (axial); local +Y (across) -> tangential;
    local +Z (shaft/radial) -> radial. See the module docstring for why.
    """
    a = math.radians(quadrant * 90.0)
    u = adsk.core.Vector3D.create(math.cos(a), math.sin(a), 0.0)
    v = adsk.core.Vector3D.create(-math.sin(a), math.cos(a), 0.0)
    z_axis = adsk.core.Vector3D.create(0.0, 0.0, 1.0)
    origin = adsk.core.Point3D.create(
        u.x * origin_r / 10.0, u.y * origin_r / 10.0, HINGE_Z / 10.0)

    m = adsk.core.Matrix3D.create()
    m.setToAlignCoordinateSystems(
        adsk.core.Point3D.create(0.0, 0.0, 0.0),
        adsk.core.Vector3D.create(1.0, 0.0, 0.0),
        adsk.core.Vector3D.create(0.0, 1.0, 0.0),
        adsk.core.Vector3D.create(0.0, 0.0, 1.0),
        origin, z_axis, v, u)

    copy = tbm.copy(body)
    if not tbm.transform(copy, m):
        raise ValueError("transform did not take")
    return copy


def _placed_name(base, q):
    return "%s q%d" % (base, q)


def _place_component(comp, body_names, origin_r, expected_count):
    """Shared PLACE/RENAME/CLEANUP/DONE logic for Servo (3 body names) and Bearing (1).

    See the module docstring for why this is four states across up to three script runs,
    not one build-and-rename pass.
    """
    placed_names = set(_placed_name(n, q) for n in body_names for q in range(4))
    old_bodies = [b for b in comp.bRepBodies if b.name in body_names]
    new_named = [b for b in comp.bRepBodies if b.name in placed_names]
    unnamed = [b for b in comp.bRepBodies
              if b.name not in body_names and b.name not in placed_names]

    if old_bodies and not unnamed and not new_named:
        _do_place(comp, body_names, origin_r)
    elif old_bodies and unnamed:
        _do_rename(comp, body_names, unnamed)
    elif old_bodies and new_named and not unnamed:
        _do_cleanup(comp, body_names)
    elif new_named and not old_bodies and not unnamed:
        print("%s already placed and cleaned up -- verifying" % comp.name)
        _verify_placed(comp, body_names, expected_count)
    else:
        raise ValueError("%s is in an unrecognised state (%d old, %d named, %d unnamed)"
                         % (comp.name, len(old_bodies), len(new_named), len(unnamed)))


def _do_place(comp, body_names, origin_r):
    """PLACE phase: add the twelve/four placed copies into a NEW BaseFeature, whatever
    default names Fusion gives them. Does not touch the old M2 bodies at all -- nothing
    is deleted or renamed in this phase.
    """
    tbm = adsk.fusion.TemporaryBRepManager.get()
    originals = {b.name: b for b in comp.bRepBodies if b.name in body_names}
    missing = [n for n in body_names if n not in originals]
    if missing:
        raise ValueError("%s is missing expected bodies: %s" % (comp.name, missing))

    made = []
    for q in range(4):
        for name in body_names:
            copy = _place_hinge_frame(tbm, originals[name], q, origin_r)
            made.append(copy)

    bf = comp.features.baseFeatures.add()
    bf.startEdit()
    for body in made:
        comp.bRepBodies.add(body, bf)
    bf.finishEdit()

    print("PLACE: added %d bodies to %s with default names -- run again to identify and "
          "rename them" % (len(made), comp.name))


def _do_rename(comp, body_names, unnamed):
    """RENAME phase: identify each default-named body by MEASURING it -- volume against
    the still-present, still-correctly-named old bodies (a rigid transform cannot change
    volume) and centre-of-mass angle against the four quadrants -- then rename it. Not by
    trusting insertion order or anything set during PLACE's own transaction.
    """
    acc = adsk.fusion.CalculationAccuracy.VeryHighCalculationAccuracy
    vol_to_name = {}
    for b in comp.bRepBodies:
        if b.name in body_names:
            vol_to_name[round(b.getPhysicalProperties(acc).volume * 1e3, 4)] = b.name
    angle_to_q = {0.0: 0, 90.0: 1, 180.0: 2, 270.0: 3}

    renamed = []
    for b in unnamed:
        props = b.getPhysicalProperties(acc)
        v = round(props.volume * 1e3, 4)
        angle = round(math.degrees(math.atan2(props.centerOfMass.y, props.centerOfMass.x))
                     % 360.0, 1)
        base = vol_to_name.get(v)
        q = angle_to_q.get(angle)
        if base is None or q is None:
            raise ValueError("%s: cannot identify body %r (volume %.4f mm3, angle %.1f deg)"
                             % (comp.name, b.name, v, angle))
        b.name = _placed_name(base, q)
        renamed.append(b.name)

    print("RENAME: identified and renamed %d bodies in %s by volume+angle -- run again "
          "to remove the old bodies" % (len(renamed), comp.name))


def _do_cleanup(comp, body_names):
    """CLEANUP phase: delete the OLD BaseFeature (the M2 originals) now that the placed
    copies are correctly named in their own, separate BaseFeature. A single-purpose
    transaction that only deletes -- nothing is created or renamed in it.
    """
    # Identify the OLD BaseFeature the same way _place_component tells old from new: any
    # BaseFeature whose sourceBodies are all named exactly one of `body_names`.
    for bf_old in list(comp.features.baseFeatures):
        names = set(b.name for b in bf_old.sourceBodies)
        if names and names.issubset(set(body_names)):
            bf_old.deleteMe()

    print("CLEANUP: removed the old BaseFeature from %s -- %d bodies remain"
          % (comp.name, comp.bRepBodies.count))


def _verify_placed(comp, body_names, expected_count):
    acc = adsk.fusion.CalculationAccuracy.VeryHighCalculationAccuracy
    if comp.bRepBodies.count != expected_count:
        raise ValueError("VERIFY FAILED: %s has %d bodies, wanted %d"
                         % (comp.name, comp.bRepBodies.count, expected_count))
    bad = []
    for q in range(4):
        want_angle = (q * 90.0) % 360.0
        for name in body_names:
            full_name = _placed_name(name, q)
            body = None
            for b in comp.bRepBodies:
                if b.name == full_name:
                    body = b
            if body is None:
                bad.append("%s is missing" % full_name)
                continue
            props = body.getPhysicalProperties(acc)
            com = props.centerOfMass
            got_angle = math.degrees(math.atan2(com.y, com.x)) % 360.0
            d = min(abs(got_angle - want_angle), 360.0 - abs(got_angle - want_angle))
            print("  %-20s angle %8.4f deg (want %6.1f, delta %.6f)"
                  % (full_name, got_angle, want_angle, d))
            if d > ANGLE_TOLERANCE_DEG:
                bad.append("%s is at %.6f deg, wanted %.1f" % (full_name, got_angle, want_angle))
    if bad:
        raise ValueError("VERIFY FAILED: " + "; ".join(bad))
    print("  OK")


def run(_context: str):
    app = adsk.core.Application.get()
    des = adsk.fusion.Design.cast(app.activeProduct)
    root = des.rootComponent

    servo_occ = _find(root, "Servo")
    _place_component(servo_occ.component, ["servo body", "servo spline", "servo boss"],
                     SERVO_ORIGIN_R, 12)

    bearing_occ = _find(root, "Bearing")
    _place_component(bearing_occ.component, ["bearing"], BEARING_ORIGIN_R, 4)
